struct Holding<'a> {
    cell: Vec<&'a (dyn Test + 'a)>,
}

trait Test {
    fn get_array(&self) -> &[u8];
}

struct Test<const N: usize> {
    array: [u8; N],
}

impl<const N: usize> Test for Test<N> {
    fn get_array(&self) -> &[u8] {
        &self.array
