import React, { useEffect, useRef, useState } from 'react';
import cytoscape from 'cytoscape';
import { connect, useSelector, useDispatch } from 'react-redux';
import { fetchData } from '../actions/graphActions';
import cxtmenu from 'cytoscape-cxtmenu';
import dagre from 'cytoscape-dagre';

cytoscape.use(cxtmenu);
cytoscape.use(dagre);

const VisNetwork = ({ fetchData, data }) => {
  const dispatch = useDispatch();
  const cyRef = useRef(null);
  const [cy, setCy] = useState(null);

  useEffect(() => {
    dispatch(fetchData());
  }, [dispatch]);

  useEffect(() => {
    if (data && !cy) {
      const cyInstance = cytoscape({
        container: cyRef.current,
        elements: data,
        layout: { name: 'dagre' },
        cxtmenu: {
          // Add your context menu configuration here
        },
      });
      setCy(cyInstance);
    } else if (data && cy) {
      cy.json({ elements: data });
    }
  }, [data, cy]);

  return <div id="cy" ref={cyRef} style={{ width: '100%', height: '100%' }} />;
};

const mapStateToProps = (state) => ({
  data: state.graph.data,
});

const mapDispatchToProps = {
  fetchData,
};

export default connect(mapStateToProps, mapDispatchToProps)(VisNetwork);
```

