struct fsa {
    size_t head;
};

size_t FSARequiredPoolSize(size_t num_of_blocks, size_t block_size) {
    block_size = ALIGN(block_size);
    return (sizeof(fsa_t) + (block_size * num_of_blocks) + sizeof(size_t));
}

fsa_t *FSAInit(void *memory_pool, size_t num_of_blocks, size_t block_size) {
    fsa_t *fsa = NULL;
    char *runner = NULL;
    size_t offset = 0;
    size_t i = 0;

    assert(memory_pool);

    block_size = ALIGN(block_size);
    fsa = (fsa_t *)ALIGN((size_t)memory_pool);

    offset = sizeof(fsa_t);

    fsa->head = offset;
    runner = (char *)fsa + offset;

    for (i = 0; i < num_of_blocks; ++i) {
        offset += block_size;
        *(size_t *)runner = (char *)fsa + offset;
        runner += block_size;
    }

    *(size_t *)runner = 0;

    return fsa;
}

void *FSAAllocate(fsa_t *fsa) {
    void *result = NULL;

    assert(fsa);

    if (0 != fsa->head) {
        result = (char *)fsa + fsa->head;
        fsa->head = *(size_t *)result;
    }

    return result;
}

void FSAFree(fsa_t *fsa, void *block) {
    assert(fsa);
    assert(block);

    *(size_t *)block = fsa->head;
    fsa->head = (char *)block - (char *)fsa;
}

size_t FSACountFree(const fsa_t *fsa) {
    size_t counter = 0;
    size_t offset = 0;

    assert(fsa);

    offset = fsa->head;

    while (0 != *(size_t *)((const char *)fsa + offset)) {
